let L = 0;
export function setLang(lang) { L = Math.max(0, LANGS.indexOf(lang)); }
export const lang = () => LANGS[L];
// t("key") → the string; t("key", a, b) → the function's result
export function t(key, ...args) {
  const v = S[key];
  if (!v) return key;
  const s = v[L] ?? v[0];
  return typeof s === "function" ? s(...args) : s;
}
export const cantonName = (ct) => (CANTON[ct] ? CANTON[ct][L] : ct);
export const pick = (o) => (o ? o[lang()] || o.de || o.fr || o.it || "" : "");
